22	// A Helm chart or a Kustomize overlay is validated after it is rendered
23	// (§3.80). Both renderers are optional: without them the directory is
24	// reported as not rendered, never as clean, and never as a missing tool —
25	// the schema stage did all it could.
26	//
27	// Measured on helm v4.3.0's sources (pkg/cmd/lint.go and
28	// pkg/chart/v2/lint/support/message.go) and kustomize v5.8.1's Dockerfile:
29	// alpine/helm's entrypoint is `helm`, the kustomize image's is
30	// /app/kustomize, so in both the arguments follow the image name.
31	
32	// Default images for the two renderers.
33	const (
34		DefaultHelmImage      = "alpine/helm"
35		DefaultKustomizeImage = "registry.k8s.io/kustomize/kustomize:v5.8.1"
36	)
37	
38	// IDs of the findings the renderers themselves produce.
39	const (
40		// HelmLintID is a message helm lint reported, at WARNING or ERROR.
41		HelmLintID = "HELM-LINT"
42		// K8sRenderID is a chart or an overlay that did not render at all.
43		K8sRenderID = "K8S-RENDER"
44	)
45	
46	// helmLintLine is one message of helm lint: `[SEVERITY] path: message`, as
47	// support.Message.Error formats it.
48	var helmLintLine = regexp.MustCompile(`^\[(ERROR|WARNING|INFO|UNKNOWN)\] ([^:]*): (.*)$`)
49	
50	// helmSourceLine is the comment helm template writes above each document,
51	// naming the template it came from: `# Source: <chart name>/templates/x.yaml`.
52	var helmSourceLine = regexp.MustCompile(`^# Source: (\S+)`)
53	
54	// renderScope is where a renderer runs. A binary runs in the target and sees
55	// the whole host. A container sees only mount, read-only at /scan, and works in
56	// the target inside it: mount is the target itself, or the git repository
57	// holding it, so an overlay or a chart can reach a sibling of the target as it
58	// does on the host (DEVDESK-742).
59	type renderScope struct {
60		target string
61		mount  string
62		// rel is the target relative to mount, with forward slashes; "" when the
63		// target is what is mounted.
64		rel string
65	}
66	
67	// targetOnly mounts the target and nothing else.
68	func targetOnly(target string) renderScope { return renderScope{target: target, mount: target} }
69	
70	// workdir is the target inside the container.
71	func (s renderScope) workdir() string { return path.Join(containerScanPath, s.rel) }
72	
73	// userHomeDir is the home directory the mount guard keeps out of reach. Tests
74	// swap it.
75	var userHomeDir = os.UserHomeDir
76	
77	// resolveRenderScope asks git, in the target, for the repository holding it.
78	// Without an answer (no git, not a repository), or when the repository's
79	// configuration moves its work tree elsewhere (core.worktree, which a cloned
80	// .git file can bring along), the target alone is mounted.
81	func resolveRenderScope(ctx context.Context, target string) renderScope {
82		git := func(args ...string) ([]byte, error) {
83			return runner.Run(ctx, toolCmd{Name: "git", Args: args, Dir: target, Env: gitEnviron(os.Environ())}, nil)
84		}
85		out, err := git("rev-parse", "--show-toplevel")
86		if err != nil {
87			log.Printf("[scan/k8s] %s: no git repository to mount, the renderers see the target only: %v", target, err)
88			return targetOnly(target)
89		}
90		worktree, err := git("config", "--get", "core.worktree")
91		var exitErr *exitError
92		unset := errors.As(err, &exitErr) && exitErr.Code == 1 && len(bytes.TrimSpace(worktree)) == 0
93		if !unset {
94			log.Printf("[scan/k8s] %s: core.worktree is set or unreadable (%q, %v), the renderers see the target only",
95				target, strings.TrimSpace(string(worktree)), err)
96			return targetOnly(target)
97		}
98		scope, ok := widerScope(target, strings.TrimSpace(string(out)))
99		if !ok {
100			return targetOnly(target)
101		}
102		log.Printf("[scan/k8s] renderers in a container mount %s, the repository holding %s", scope.mount, target)
103		return scope
104	}
