106	// gitEnviron is env without the variables that point git at another
107	// repository, work tree or configuration: the mount is decided by the target
108	// alone. GIT_CEILING_DIRECTORIES stays: it can only stop git's search for the
109	// repository earlier, and dropping it would widen what the user limited.
110	func gitEnviron(env []string) []string {
111		out := make([]string, 0, len(env))
112		for _, kv := range env {
113			name, _, _ := strings.Cut(kv, "=")
114			switch {
115			case name == "GIT_DIR", name == "GIT_WORK_TREE", name == "GIT_COMMON_DIR",
116				strings.HasPrefix(name, "GIT_CONFIG"):
117				continue
118			}
119			out = append(out, kv)
120		}
121		return out
122	}
