124	// widerScope mounts top, the repository git named, when it is safe to: top is
125	// a strict ancestor of the target once symlinks are resolved, neither the
126	// filesystem root nor the home directory nor anything above it, and it holds
127	// the repository's .git itself (gitDirIsHere). Anything else, an unknown home
128	// included, keeps the target alone.
129	func widerScope(target, top string) (renderScope, bool) {
130		if top == "" || !filepath.IsAbs(top) {
131			return renderScope{}, false
132		}
133		root, err := filepath.EvalSymlinks(top)
134		if err != nil {
135			return renderScope{}, false
136		}
137		real, err := filepath.EvalSymlinks(target)
138		if err != nil {
139			return renderScope{}, false
140		}
141		rel, err := filepath.Rel(root, real)
142		if err != nil || rel == "." || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
143			return renderScope{}, false
144		}
145		if filepath.Dir(root) == root {
146			return renderScope{}, false
147		}
148		home, err := userHomeDir()
149		if err != nil || home == "" {
150			return renderScope{}, false
151		}
152		if h, err := filepath.EvalSymlinks(home); err == nil {
153			home = h
154		}
155		if r, err := filepath.Rel(root, filepath.Clean(home)); err == nil &&
156			(r == "." || (r != ".." && !strings.HasPrefix(r, ".."+string(filepath.Separator)))) {
157			return renderScope{}, false
158		}
159		if !gitDirIsHere(root) {
160			return renderScope{}, false
161		}
162		return renderScope{target: target, mount: root, rel: filepath.ToSlash(rel)}, true
163	}
