165	// maxGitFile bounds what is read of a .git file or a worktree's gitdir file:
166	// one line, a path.
167	const maxGitFile = 4096
168	
169	// gitDirIsHere reports whether root holds its repository's .git: a directory,
170	// or the file of a linked worktree ("gitdir: <dir>") whose git directory names
171	// root's .git back in its own gitdir file. A symlink, a file that says
172	// anything else, or a git directory that does not point back is refused: git
173	// was then told where the work tree is, rather than finding it.
174	func gitDirIsHere(root string) bool {
175		dotGit := filepath.Join(root, ".git")
176		info, err := os.Lstat(dotGit)
177		if err != nil {
178			return false
179		}
180		if info.IsDir() {
181			return true
182		}
183		if !info.Mode().IsRegular() {
184			return false
185		}
186		line, ok := readGitFile(dotGit)
187		gitDir, found := strings.CutPrefix(line, "gitdir: ")
188		if !ok || !found {
189			return false
190		}
191		if !filepath.IsAbs(gitDir) {
192			gitDir = filepath.Join(root, gitDir)
193		}
194		back, ok := readGitFile(filepath.Join(gitDir, "gitdir"))
195		if !ok {
196			return false
197		}
198		if !filepath.IsAbs(back) {
199			back = filepath.Join(gitDir, back)
200		}
201		a, errA := filepath.EvalSymlinks(back)
202		b, errB := filepath.EvalSymlinks(dotGit)
203		return errA == nil && errB == nil && a == b
204	}
