206	// readGitFile reads the one line of a small regular file.
207	func readGitFile(p string) (string, bool) {
208		info, err := os.Lstat(p)
209		if err != nil || !info.Mode().IsRegular() || info.Size() > maxGitFile {
210			return "", false
211		}
212		data, err := os.ReadFile(p) //nolint:gosec // a .git file of the repository being scanned
213		if err != nil {
214			return "", false
215		}
216		return strings.TrimSpace(string(data)), true
217	}
