219	// renderer runs one tool in the repository, the way every other tool runs:
220	// in the target for a binary; for an image, with the scope's mount read-only
221	// at /scan and the target inside it as the working directory.
222	func renderer(scope renderScope, tool ToolSpec, defaultImage, binary string, args ...string) toolCmd {
223		// helm gets them on lint and on template alike: only the flags the two
224		// share (--values, --set…) make sense there.
225		args = afterSubcommand(args, tool.Args)
226		if tool.Source != ToolSourceContainer {
227			name := tool.Binary
228			if name == "" {
229				name = binary
230			}
231			return toolCmd{Name: name, Args: args, Dir: scope.target}
232		}
233		return containerRun{
234			Flags: []string{"-v", scope.mount + ":" + containerScanPath + ":ro", "-w", scope.workdir()},
235			Image: orDefault(tool.Image, defaultImage),
236			Argv:  args,
237		}.cmd()
238	}
