338	// renderKustomizations builds and validates each overlay. Without kustomize,
339	// every overlay is reported as not rendered.
340	func (v *k8sValidation) renderKustomizations(ctx context.Context, dirs []string) error {
341		tool := v.opts.Kustomize
342		for _, dir := range dirs {
343			if !available(tool) {
344				v.report.Unrendered = append(v.report.Unrendered, dir)
345				continue
346			}
347			file := path.Join(dir, k8s.KustomizationFile(filepath.Join(v.target, filepath.FromSlash(dir))))
348			cmd := kustomizeArgs(v.scope, dir, tool)
349			log.Printf("Running: %s", cmd)
350			rendered, err := runner.Run(ctx, cmd, nil)
351			if err != nil {
352				if ctx.Err() != nil {
353					return ctx.Err()
354				}
355				repro, from := renderRepro(tool, "kustomize", "build", dir)
356				v.report.Findings = append(v.report.Findings,
357					renderFailure(SourceKustomize, "kustomize", file, "Overlay does not build", from,
358						renderSteps(SourceKustomize, dir, from, failureDetail(err)), repro, err))
359				continue
360			}
361			// kustomize adds no origin to what it emits unless the kustomization
362			// asks for it, and DevDesk does not write into the file to ask. The
363			// overlay is what was built, so it is what a finding points at.
364			err = v.validateRendered(ctx, rendered, "kustomize", func(string, string) string { return file })
365			if err != nil {
366				return fmt.Errorf("overlay %s: %w", dir, err)
367			}
368		}
369		return nil
370	}
