398	// helmLint runs helm lint and returns its warnings and errors. helm exits 1
399	// when a chart fails; its messages are still the answer. A run that printed
400	// nothing parseable is logged and yields nothing — the render that follows
401	// will say whether the chart is usable.
402	func helmLint(ctx context.Context, scope renderScope, chart string, tool ToolSpec) []Finding {
403		cmd := helmArgs(scope, chart, tool, "lint")
404		log.Printf("Running: %s", cmd)
405		out, err := runner.Run(ctx, cmd, nil)
406		findings, recognised := parseHelmLint(out, chart, scope)
407		if err != nil && !recognised {
408			log.Printf("ERROR [scan/helm] lint %s: %v", chart, err)
409		}
410		repro, from := renderRepro(tool, "helm", "lint", chart)
411		for i := range findings {
412			findings[i].Repro, findings[i].RanFrom = repro, from
413		}
414		return findings
415	}
416	
417	// parseHelmLint turns helm lint's text into findings. The second result says
418	// the output was helm lint's at all.
419	//
420	// A message's path is usually relative to the chart ("templates/cm.yaml"),
421	// but not always: the missing-dependency warning names the chart directory
422	// absolutely — "/scan/charts/broken" in a container, measured on helm 4.3.0.
423	// Both are brought back to a path relative to the target.
424	func parseHelmLint(out []byte, chart string, scope renderScope) ([]Finding, bool) {
425		file := func(p string) string { return helmLintPath(p, chart, scope) }
426		var findings []Finding
427		recognised := false
428		sc := bufio.NewScanner(bytes.NewReader(out))
429		for sc.Scan() {
430			line := strings.TrimSpace(sc.Text())
431			switch {
432			case strings.HasPrefix(line, "==> Linting"):
433				recognised = true
434			case strings.HasPrefix(line, "Error "):
435				// Printed instead of the messages when the chart could not be
436				// loaded at all.
437				recognised = true
438				findings = append(findings, helmLintFinding(chart, chart, SeverityHigh, strings.TrimPrefix(line, "Error ")))
439			default:
440				m := helmLintLine.FindStringSubmatch(line)
441				if m == nil {
442					continue
443				}
444				recognised = true
445				switch m[1] {
446				case "ERROR":
447					findings = append(findings, helmLintFinding(chart, file(m[2]), SeverityHigh, m[3]))
448				case "WARNING":
449					findings = append(findings, helmLintFinding(chart, file(m[2]), SeverityLow, m[3]))
450				}
451			}
452		}
453		return findings, recognised
454	}
455	
456	// helmLintPath resolves a path helm lint printed to one relative to the
457	// target. In a container the target is the scope's working directory, which is
458	// /scan itself unless the git repository around the target is mounted.
459	func helmLintPath(p, chart string, scope renderScope) string {
460		p = strings.TrimSuffix(p, "/")
461		switch {
462		case p == containerScanPath || strings.HasPrefix(p, containerScanPath+"/"):
463			if rel, err := filepath.Rel(filepath.FromSlash(scope.workdir()), filepath.FromSlash(p)); err == nil {
464				return filepath.ToSlash(rel)
465			}
466			return p
467		case filepath.IsAbs(p):
468			if rel, err := filepath.Rel(scope.target, p); err == nil && !strings.HasPrefix(rel, "..") {
469				return filepath.ToSlash(rel)
470			}
471			return filepath.ToSlash(p)
472		default:
473			return path.Join(chart, p)
474		}
475	}
