225	// fileReader reads a file relative to root, for locating a finding's line.
226	func fileReader(root string) func(string) ([]byte, error) {
227		return func(name string) ([]byte, error) {
228			return os.ReadFile(filepath.Join(root, filepath.FromSlash(name))) //nolint:gosec // a manifest of the repository being scanned
229		}
230	}
