1	// Package k8s reads Kubernetes manifests as files — which of a repository's
2	// YAML files are manifests, which directories are Helm charts or Kustomize
3	// roots, and where inside a manifest a JSON pointer lands (§3.80).
4	//
5	// It never talks to a cluster and runs no tool: it is pure file reading, so
6	// the scan stage that drives kubeconform, helm and kustomize can be tested
7	// without any of them.
8	package k8s
9	
10	import (
11		"bytes"
12		"errors"
13		"io"
14		"io/fs"
15		"os"
16		"path/filepath"
17		"sort"
18		"strings"
19	
20		"gopkg.in/yaml.v3"
21	)
22	
23	// maxManifestSize bounds what is read to decide whether a file is a manifest.
24	// A generated bundle can be large, but a YAML file of several megabytes in a
25	// repository is data, not something anyone applies by hand.
26	const maxManifestSize = 4 << 20
27	
28	// kustomizationFiles are the names kustomize accepts for a root, in the order
29	// it looks for them.
30	var kustomizationFiles = []string{"kustomization.yaml", "kustomization.yml", "Kustomization"}
31	
32	// skippedDirs are never descended into: dependencies and tool state, not the
33	// repository's own manifests.
34	var skippedDirs = map[string]bool{
35		"node_modules": true,
36		"vendor":       true,
37	}
38	
39	// Layout is what a repository holds in the way of Kubernetes configuration.
40	// Every path is relative to the root, with forward slashes.
41	type Layout struct {
42		// Manifests are the plain YAML files that carry at least one document
43		// with an apiVersion and a kind, outside any chart or Kustomize root.
44		Manifests []string
45		// Charts are the directories holding a Chart.yaml that is not a subchart
46		// of another one — a subchart is rendered by its parent.
47		Charts []string
48		// Kustomizations are the Kustomize roots nothing else references: the
49		// overlays. A base is rendered through the overlays that use it, and
50		// rendering it alone would validate a configuration nobody deploys.
51		Kustomizations []string
52	}
53	
54	// Discover walks root and sorts what it finds into a Layout.
55	//
56	// A file inside a chart or under a Kustomize root is never a plain manifest:
57	// a template is not YAML until helm renders it, and a Kustomize patch is a
58	// fragment that fails schema validation on its own — it is only a resource
59	// once kustomize has merged it. Both are validated after rendering, or not at
60	// all when the tool that renders them is absent.
61	//
62	// Which YAML files are manifests is decided by content, not by name: a
63	// document with an apiVersion and a kind. That is what Trivy does too, and
64	// what keeps a CI configuration or a docker-compose file out.
65	func Discover(root string) (Layout, error) {
66		var charts, kustomizeRoots, candidates []string
67	
68		err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
69			if err != nil {
70				// An unreadable entry costs itself, not the walk; only the root
71				// failing means there is nothing to discover.
72				if path == root {
73					return err
74				}
75				if d != nil && d.IsDir() {
76					return filepath.SkipDir
77				}
78				return nil
79			}
80			if d.IsDir() {
81				name := d.Name()
82				if path != root && (strings.HasPrefix(name, ".") || skippedDirs[name]) {
83					return filepath.SkipDir
84				}
85				if fileExists(filepath.Join(path, "Chart.yaml")) {
86					charts = append(charts, path)
87				}
88				if kustomizationIn(path) != "" {
89					kustomizeRoots = append(kustomizeRoots, path)
90				}
91				return nil
92			}
93			if isYAMLName(d.Name()) {
94				candidates = append(candidates, path)
95			}
96			return nil
97		})
98		if err != nil {
99			return Layout{}, err
100		}
101	
102		var layout Layout
103		for _, c := range outermost(charts) {
104			layout.Charts = append(layout.Charts, rel(root, c))
105		}
106		for _, k := range leaves(kustomizeRoots) {
107			layout.Kustomizations = append(layout.Kustomizations, rel(root, k))
108		}
109		excluded := append(append([]string{}, charts...), kustomizeRoots...)
110		for _, path := range candidates {
111			if under(path, excluded) {
112				continue
113			}
114			if content, err := readBounded(path); err == nil && IsManifest(content) {
115				layout.Manifests = append(layout.Manifests, rel(root, path))
116			}
117		}
118		sort.Strings(layout.Manifests)
119		sort.Strings(layout.Charts)
120		sort.Strings(layout.Kustomizations)
121		return layout, nil
122	}
123	
124	// IsManifest reports whether any document of a YAML file has an apiVersion
125	// and a kind at its top level. A file that does not parse is not one: it
126	// cannot be applied either, but saying so is a linter's job, and the file may
127	// well not be meant for Kubernetes at all.
128	func IsManifest(content []byte) bool {
129		dec := yaml.NewDecoder(bytes.NewReader(content))
130		for {
131			var doc map[string]any
132			err := dec.Decode(&doc)
133			if errors.Is(err, io.EOF) {
134				return false
135			}
136			if err != nil {
137				return false
138			}
139			if _, ok := doc["apiVersion"].(string); !ok {
140				continue
141			}
142			if _, ok := doc["kind"].(string); ok {
143				return true
144			}
145		}
146	}
147	
148	// KustomizationFile returns the name of dir's Kustomize file, or "" when dir
149	// is not a Kustomize root.
150	func KustomizationFile(dir string) string {
151		if p := kustomizationIn(dir); p != "" {
152			return filepath.Base(p)
153		}
154		return ""
155	}
156	
157	// kustomizationIn returns the path of dir's Kustomize file, or "".
158	func kustomizationIn(dir string) string {
159		for _, name := range kustomizationFiles {
160			p := filepath.Join(dir, name)
161			if fileExists(p) {
162				return p
163			}
164		}
165		return ""
166	}
167	
168	// kustomizationRefs are the fields through which one root pulls in another.
169	type kustomizationRefs struct {
170		Resources  []string `yaml:"resources"`
171		Bases      []string `yaml:"bases"`
172		Components []string `yaml:"components"`
173	}
174	
175	// leaves drops every Kustomize root another one references. A reference that
176	// names a file rather than a directory, or a remote URL, references no root
177	// and is ignored; a kustomization that does not parse references nothing and
178	// stays a leaf, so kustomize itself gets to say what is wrong with it.
179	func leaves(roots []string) []string {
180		referenced := map[string]bool{}
181		for _, r := range roots {
182			content, err := readBounded(kustomizationIn(r))
183			if err != nil {
184				continue
185			}
186			var refs kustomizationRefs
187			if yaml.Unmarshal(content, &refs) != nil {
188				continue
189			}
190			for _, list := range [][]string{refs.Resources, refs.Bases, refs.Components} {
191				for _, ref := range list {
192					if strings.Contains(ref, "://") {
193						continue
194					}
195					referenced[filepath.Clean(filepath.Join(r, ref))] = true
196				}
197			}
198		}
199		var out []string
200		for _, r := range roots {
201			if !referenced[filepath.Clean(r)] {
202				out = append(out, r)
203			}
204		}
205		return out
206	}
207	
208	// outermost drops every chart nested in another: helm renders a subchart as
209	// part of its parent, with the parent's values.
210	func outermost(dirs []string) []string {
211		var out []string
212		for _, d := range dirs {
213			nested := false
214			for _, other := range dirs {
215				if other != d && isUnder(d, other) {
216					nested = true
217					break
218				}
219			}
220			if !nested {
221				out = append(out, d)
222			}
223		}
224		return out
225	}
226	
227	func under(path string, dirs []string) bool {
228		for _, d := range dirs {
229			if isUnder(path, d) {
230				return true
231			}
232		}
233		return false
234	}
235	
236	// isUnder reports whether path lies inside dir, dir itself excluded.
237	func isUnder(path, dir string) bool {
238		r, err := filepath.Rel(dir, path)
239		return err == nil && r != "." && r != ".." && !strings.HasPrefix(r, ".."+string(filepath.Separator))
240	}
241	
242	func rel(root, path string) string {
243		r, err := filepath.Rel(root, path)
244		if err != nil {
245			return filepath.ToSlash(path)
246		}
247		return filepath.ToSlash(r)
248	}
249	
250	func isYAMLName(name string) bool {
251		ext := strings.ToLower(filepath.Ext(name))
252		return ext == ".yaml" || ext == ".yml"
253	}
254	
255	func fileExists(path string) bool {
256		info, err := os.Stat(path)
257		return err == nil && !info.IsDir()
258	}
259	
260	// readBounded reads a regular file unless it is larger than maxManifestSize.
261	// Like ReadManifestIn it judges the handle it opened, without blocking on a
262	// FIFO, so a FIFO or a device named like a manifest or a kustomization is
263	// refused rather than waited on.
264	func readBounded(path string) ([]byte, error) {
265		f, err := os.OpenFile(path, os.O_RDONLY|nonBlock, 0) //nolint:gosec // a file of the repository being scanned
266		if err != nil {
267			return nil, err
268		}
269		defer func() { _ = f.Close() }()
270		return readRegular(f)
271	}
272	
273	// ReadManifestIn reads a file of root, which it cannot leave (a ".." or a
274	// symlink pointing out is refused), under the same size bound as readBounded.
275	// It opens the file once and judges that handle: a FIFO or a device is refused
276	// whatever Stat said a moment earlier, and the read itself is bounded, so a
277	// file that grows after the check cannot be read whole.
278	func ReadManifestIn(root *os.Root, name string) ([]byte, error) {
279		// nonBlock lets a FIFO open without waiting for a writer, so the check
280		// below can refuse it.
281		f, err := root.OpenFile(name, os.O_RDONLY|nonBlock, 0)
282		if err != nil {
283			return nil, err
284		}
285		defer func() { _ = f.Close() }()
286		return readRegular(f)
287	}
288	
289	// readRegular reads an open file, refusing anything but a regular file and
290	// reading no more than maxManifestSize, so a file that grows after the check
291	// cannot be read whole.
292	func readRegular(f *os.File) ([]byte, error) {
293		info, err := f.Stat()
294		if err != nil {
295			return nil, err
296		}
297		if !info.Mode().IsRegular() {
298			return nil, errors.New("not a regular file")
299		}
300		data, err := io.ReadAll(io.LimitReader(f, maxManifestSize+1))
301		if err != nil {
302			return nil, err
303		}
304		if len(data) > maxManifestSize {
305			return nil, errors.New("too large to be a hand-written manifest")
306		}
307		return data, nil
308	}
