1	package scan
2	
3	import (
4		"bufio"
5		"bytes"
6		"context"
7		"errors"
8		"fmt"
9		"io"
10		"log"
11		"os"
12		"path"
13		"path/filepath"
14		"regexp"
15		"strings"
16	
17		"gopkg.in/yaml.v3"
18	
19		"github.com/anthnel/devdesk/internal/k8s"
20	)
21	
22	// A Helm chart or a Kustomize overlay is validated after it is rendered
23	// (§3.80). Both renderers are optional: without them the directory is
24	// reported as not rendered, never as clean, and never as a missing tool —
25	// the schema stage did all it could.
26	//
27	// Measured on helm v4.3.0's sources (pkg/cmd/lint.go and
28	// pkg/chart/v2/lint/support/message.go) and kustomize v5.8.1's Dockerfile:
29	// alpine/helm's entrypoint is `helm`, the kustomize image's is
30	// /app/kustomize, so in both the arguments follow the image name.
31	
32	// Default images for the two renderers.
33	const (
34		DefaultHelmImage      = "alpine/helm"
35		DefaultKustomizeImage = "registry.k8s.io/kustomize/kustomize:v5.8.1"
36	)
37	
38	// IDs of the findings the renderers themselves produce.
39	const (
40		// HelmLintID is a message helm lint reported, at WARNING or ERROR.
41		HelmLintID = "HELM-LINT"
42		// K8sRenderID is a chart or an overlay that did not render at all.
43		K8sRenderID = "K8S-RENDER"
44	)
45	
46	// helmLintLine is one message of helm lint: `[SEVERITY] path: message`, as
47	// support.Message.Error formats it.
48	var helmLintLine = regexp.MustCompile(`^\[(ERROR|WARNING|INFO|UNKNOWN)\] ([^:]*): (.*)$`)
49	
50	// helmSourceLine is the comment helm template writes above each document,
51	// naming the template it came from: `# Source: <chart name>/templates/x.yaml`.
52	var helmSourceLine = regexp.MustCompile(`^# Source: (\S+)`)
53	
54	// renderScope is where a renderer runs. A binary runs in the target and sees
55	// the whole host. A container sees only mount, read-only at /scan, and works in
56	// the target inside it: mount is the target itself, or the git repository
57	// holding it, so an overlay or a chart can reach a sibling of the target as it
58	// does on the host (DEVDESK-742).
59	type renderScope struct {
60		target string
61		mount  string
62		// rel is the target relative to mount, with forward slashes; "" when the
63		// target is what is mounted.
64		rel string
65	}
66	
67	// targetOnly mounts the target and nothing else.
68	func targetOnly(target string) renderScope { return renderScope{target: target, mount: target} }
69	
70	// workdir is the target inside the container.
71	func (s renderScope) workdir() string { return path.Join(containerScanPath, s.rel) }
72	
73	// userHomeDir is the home directory the mount guard keeps out of reach. Tests
74	// swap it.
75	var userHomeDir = os.UserHomeDir
76	
77	// resolveRenderScope asks git, in the target, for the repository holding it.
78	// Without an answer (no git, not a repository), or when the repository's
79	// configuration moves its work tree elsewhere (core.worktree, which a cloned
80	// .git file can bring along), the target alone is mounted.
81	func resolveRenderScope(ctx context.Context, target string) renderScope {
82		git := func(args ...string) ([]byte, error) {
83			return runner.Run(ctx, toolCmd{Name: "git", Args: args, Dir: target, Env: gitEnviron(os.Environ())}, nil)
84		}
85		out, err := git("rev-parse", "--show-toplevel")
86		if err != nil {
87			log.Printf("[scan/k8s] %s: no git repository to mount, the renderers see the target only: %v", target, err)
88			return targetOnly(target)
89		}
90		worktree, err := git("config", "--get", "core.worktree")
91		var exitErr *exitError
92		unset := errors.As(err, &exitErr) && exitErr.Code == 1 && len(bytes.TrimSpace(worktree)) == 0
93		if !unset {
94			log.Printf("[scan/k8s] %s: core.worktree is set or unreadable (%q, %v), the renderers see the target only",
95				target, strings.TrimSpace(string(worktree)), err)
96			return targetOnly(target)
97		}
98		scope, ok := widerScope(target, strings.TrimSpace(string(out)))
99		if !ok {
100			return targetOnly(target)
101		}
102		log.Printf("[scan/k8s] renderers in a container mount %s, the repository holding %s", scope.mount, target)
103		return scope
104	}
105	
106	// gitEnviron is env without the variables that point git at another
107	// repository, work tree or configuration: the mount is decided by the target
108	// alone. GIT_CEILING_DIRECTORIES stays: it can only stop git's search for the
109	// repository earlier, and dropping it would widen what the user limited.
110	func gitEnviron(env []string) []string {
111		out := make([]string, 0, len(env))
112		for _, kv := range env {
113			name, _, _ := strings.Cut(kv, "=")
114			switch {
115			case name == "GIT_DIR", name == "GIT_WORK_TREE", name == "GIT_COMMON_DIR",
116				strings.HasPrefix(name, "GIT_CONFIG"):
117				continue
118			}
119			out = append(out, kv)
120		}
121		return out
122	}
123	
124	// widerScope mounts top, the repository git named, when it is safe to: top is
125	// a strict ancestor of the target once symlinks are resolved, neither the
126	// filesystem root nor the home directory nor anything above it, and it holds
127	// the repository's .git itself (gitDirIsHere). Anything else, an unknown home
128	// included, keeps the target alone.
129	func widerScope(target, top string) (renderScope, bool) {
130		if top == "" || !filepath.IsAbs(top) {
131			return renderScope{}, false
132		}
133		root, err := filepath.EvalSymlinks(top)
134		if err != nil {
135			return renderScope{}, false
136		}
137		real, err := filepath.EvalSymlinks(target)
138		if err != nil {
139			return renderScope{}, false
140		}
141		rel, err := filepath.Rel(root, real)
142		if err != nil || rel == "." || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
143			return renderScope{}, false
144		}
145		if filepath.Dir(root) == root {
146			return renderScope{}, false
147		}
148		home, err := userHomeDir()
149		if err != nil || home == "" {
150			return renderScope{}, false
151		}
152		if h, err := filepath.EvalSymlinks(home); err == nil {
153			home = h
154		}
155		if r, err := filepath.Rel(root, filepath.Clean(home)); err == nil &&
156			(r == "." || (r != ".." && !strings.HasPrefix(r, ".."+string(filepath.Separator)))) {
157			return renderScope{}, false
158		}
159		if !gitDirIsHere(root) {
160			return renderScope{}, false
161		}
162		return renderScope{target: target, mount: root, rel: filepath.ToSlash(rel)}, true
163	}
164	
165	// maxGitFile bounds what is read of a .git file or a worktree's gitdir file:
166	// one line, a path.
167	const maxGitFile = 4096
168	
169	// gitDirIsHere reports whether root holds its repository's .git: a directory,
170	// or the file of a linked worktree ("gitdir: <dir>") whose git directory names
171	// root's .git back in its own gitdir file. A symlink, a file that says
172	// anything else, or a git directory that does not point back is refused: git
173	// was then told where the work tree is, rather than finding it.
174	func gitDirIsHere(root string) bool {
175		dotGit := filepath.Join(root, ".git")
176		info, err := os.Lstat(dotGit)
177		if err != nil {
178			return false
179		}
180		if info.IsDir() {
181			return true
182		}
183		if !info.Mode().IsRegular() {
184			return false
185		}
186		line, ok := readGitFile(dotGit)
187		gitDir, found := strings.CutPrefix(line, "gitdir: ")
188		if !ok || !found {
189			return false
190		}
191		if !filepath.IsAbs(gitDir) {
192			gitDir = filepath.Join(root, gitDir)
193		}
194		back, ok := readGitFile(filepath.Join(gitDir, "gitdir"))
195		if !ok {
196			return false
197		}
198		if !filepath.IsAbs(back) {
199			back = filepath.Join(gitDir, back)
200		}
201		a, errA := filepath.EvalSymlinks(back)
202		b, errB := filepath.EvalSymlinks(dotGit)
203		return errA == nil && errB == nil && a == b
204	}
