247	// renderRepro is the Repro line of a renderer run on target (a chart or an
248	// overlay directory), run from the scanned directory like the scan did. The
249	// user's arguments are left out: they may hold a secret (--set password=REDACTED
250	func renderRepro(tool ToolSpec, name, sub, target string) (string, ToolSource) {
251		return localRepro(tool, name, []string{sub}, target)
252	}
