262	// kubeconformStdinArgs validates what arrives on stdin. A container gets -i
263	// and no repository mount: it reads nothing but its input and its cache.
264	func kubeconformStdinArgs(rendered []byte, tool ToolSpec, opts KubeconformOptions) toolCmd {
265		flags := kubeconformFlags(tool, opts)
266		if tool.Source != ToolSourceContainer {
267			return toolCmd{Name: kubeconformBinary(tool), Args: append(flags, "-"), Stdin: rendered}
268		}
269		engineArgs := []string{"-i"}
270		if opts.CacheDir != "" {
271			engineArgs = append(engineArgs, "-v", opts.CacheDir+":"+kubeconformCacheMount)
272		}
273		return containerRun{
274			Flags: engineArgs, Image: kubeconformImage(tool.Image), Argv: append(flags, "-"), Stdin: rendered,
275		}.cmd()
276	}
