294	// renderCharts lints, renders and validates each chart. Without helm, every
295	// chart is reported as not rendered.
296	func (v *k8sValidation) renderCharts(ctx context.Context, charts []string) error {
297		tool := v.opts.Helm
298		for _, chart := range charts {
299			if !available(tool) {
300				v.report.Unrendered = append(v.report.Unrendered, chart)
301				continue
302			}
303			lint := helmLint(ctx, v.scope, chart, tool)
304			v.report.Findings = append(v.report.Findings, lint...)
305	
306			cmd := helmArgs(v.scope, chart, tool, "template")
307			log.Printf("Running: %s", cmd)
308			rendered, err := runner.Run(ctx, cmd, nil)
309			if err != nil {
310				if ctx.Err() != nil {
311					return ctx.Err()
312				}
313				// helm lint renders the chart too, so a chart that does not
314				// render has usually been reported by it already, with more to
315				// say. The render failure is the fallback, not a second copy.
316				if !hasError(lint) {
317					repro, from := renderRepro(tool, "helm", "template", chart)
318					v.report.Findings = append(v.report.Findings,
319						renderFailure(SourceHelm, "helm", path.Join(chart, "Chart.yaml"), "Chart does not render", from,
320							renderSteps(SourceHelm, chart, from, failureDetail(err)), repro, err))
321				}
322				continue
323			}
324			origins := helmOrigins(rendered, chart)
325			err = v.validateRendered(ctx, rendered, "helm", func(kind, name string) string {
326				if file, ok := origins[kind+"/"+name]; ok {
327					return file
328				}
329				return chart
330			})
331			if err != nil {
332				return fmt.Errorf("chart %s: %w", chart, err)
333			}
334		}
335		return nil
336	}
337	
338	// renderKustomizations builds and validates each overlay. Without kustomize,
339	// every overlay is reported as not rendered.
340	func (v *k8sValidation) renderKustomizations(ctx context.Context, dirs []string) error {
341		tool := v.opts.Kustomize
342		for _, dir := range dirs {
343			if !available(tool) {
344				v.report.Unrendered = append(v.report.Unrendered, dir)
345				continue
346			}
347			file := path.Join(dir, k8s.KustomizationFile(filepath.Join(v.target, filepath.FromSlash(dir))))
348			cmd := kustomizeArgs(v.scope, dir, tool)
349			log.Printf("Running: %s", cmd)
350			rendered, err := runner.Run(ctx, cmd, nil)
351			if err != nil {
352				if ctx.Err() != nil {
353					return ctx.Err()
354				}
355				repro, from := renderRepro(tool, "kustomize", "build", dir)
356				v.report.Findings = append(v.report.Findings,
357					renderFailure(SourceKustomize, "kustomize", file, "Overlay does not build", from,
358						renderSteps(SourceKustomize, dir, from, failureDetail(err)), repro, err))
359				continue
360			}
361			// kustomize adds no origin to what it emits unless the kustomization
362			// asks for it, and DevDesk does not write into the file to ask. The
363			// overlay is what was built, so it is what a finding points at.
364			err = v.validateRendered(ctx, rendered, "kustomize", func(string, string) string { return file })
365			if err != nil {
366				return fmt.Errorf("overlay %s: %w", dir, err)
367			}
368		}
369		return nil
370	}
