372	// validateRendered runs kubeconform over rendered YAML and points each
373	// finding back at the file it came from. A rendered line is not a line of
374	// any file in the repository, so these findings carry none.
375	func (v *k8sValidation) validateRendered(ctx context.Context, rendered []byte, dialect string, origin func(kind, name string) string) error {
376		if len(bytes.TrimSpace(rendered)) == 0 {
377			return nil
378		}
379		cmd := kubeconformStdinArgs(rendered, v.kubeconform, v.opts)
380		log.Printf("Running: %s", cmd)
381		out, err := runner.Run(ctx, cmd, nil)
382		if err := kubeconformFailure(out, err); err != nil {
383			return err
384		}
385		noFile := func(string) ([]byte, error) { return nil, errors.New("rendered, not a file") }
386		findings, skipped, err := parseKubeconformReport(out, v.opts.KubernetesVersion, noFile, origin, dialect)
387		if err != nil {
388			return err
389		}
390		v.report.SkippedCustom += skipped
391		for i := range findings {
392			findings[i].IaCType = dialect
393		}
394		v.report.Findings = append(v.report.Findings, findings...)
395		return nil
396	}
