477	func helmLintFinding(chart, file string, severity SeverityLevel, msg string) Finding {
478		return Finding{
479			Steps:       helmLintSteps(file, chart),
480			ID:          HelmLintID,
481			Title:       msg,
482			Description: "helm lint reported this about the chart.",
483			Message:     msg,
484			Severity:    severity,
485			Source:      SourceHelm,
486			File:        file,
487			IaCType:     "helm",
488		}
