500	// renderFailure is a chart or an overlay that could not be rendered: nothing
501	// in it was validated, and `helm install` or `kubectl apply -k` would fail the
502	// same way.
503	//
504	// steps and repro are what the caller wrote for it (renderSteps, localRepro);
505	// from is where the renderer ran.
506	func renderFailure(source, dialect, file, title string, from ToolSource, steps []string, repro string, err error) Finding {
507		detail := failureDetail(err)
508		first, _, _ := strings.Cut(detail, "\n")
509		return Finding{
510			ID:          K8sRenderID,
511			Title:       title + ": " + first,
512			Description: "The directory could not be rendered, so none of its resources were validated.",
513			Message:     detail,
514			Resolution:  renderResolution(source, from, detail),
515			Steps:       steps,
516			Repro:       repro,
517			RanFrom:     from,
518			Severity:    SeverityHigh,
519			Source:      source,
520			File:        file,
521			IaCType:     dialect,
522		}
523	}
