534	// How to fix a chart or an overlay that does not render, in the renderer's own
535	// terms.
536	const (
537		helmRenderResolution = "Render it locally with helm template and fix what it reports; " +
538			"a chart's dependencies must be vendored in charts/ or fetched with helm dependency build."
539		kustomizeRenderResolution = "Build it locally with kustomize build (or kubectl kustomize) and fix what it reports."
540		// kustomize's load restrictor (LoadRestrictionsRootOnly, its default)
541		// refuses a file outside the kustomization's directory, with this message.
542		// The flag is not reserved (ToolKustomize.ReservedArgs) and lands after
543		// `build` (afterSubcommand), where kustomize accepts it.
544		loadRestrictorResolution = "kustomize refuses by default a file outside the overlay directory " +
545			"(same as kubectl apply -k). Reference a directory with its own kustomization instead, " +
546			"or, if your deployment tool allows it, set " +
547			"scan.tools.kustomize.args: [--load-restrictor=LoadRestrictionsNone]."
548	)
549	
550	// mountResolution is added for a kustomize image that could not find a path:
551	// the container sees only what DevDesk mounts (renderScope), and DevDesk does
552	// not walk the repository to tell a hidden reference from a broken one.
553	// ToolConfig's `source` key takes auto, binary or image.
554	const mountResolution = "If this reference points outside the directory DevDesk mounts into the container " +
555		"(the scanned directory, or its git repository when it has one), scan the enclosing directory, " +
556		"or set scan.tools.kustomize.source: binary (the binary sees the whole file system)."
557	
558	// renderResolution picks the advice for a render failure from the renderer,
559	// where it ran and what it printed.
560	func renderResolution(source string, from ToolSource, detail string) string {
561		if source != SourceKustomize {
562			return helmRenderResolution
563		}
564		advice := kustomizeRenderResolution
565		if isLoadRestrictor(detail) {
566			advice = loadRestrictorResolution
567		}
568		if from == ToolSourceContainer &&
569			(strings.Contains(detail, "evalsymlink failure") || strings.Contains(detail, "no such file or directory")) {
570			advice += " " + mountResolution
571		}
572		return advice
573	}
