575	// helmOrigins maps each rendered resource, by kind and name, to the template
576	// it came from, relative to the repository. helm names the template under the
577	// chart's own name, which need not be its directory's.
578	func helmOrigins(rendered []byte, chart string) map[string]string {
579		origins := map[string]string{}
580		for _, doc := range splitYAMLDocuments(rendered) {
581			var source string
582			for _, line := range strings.Split(doc, "\n") {
583				if m := helmSourceLine.FindStringSubmatch(line); m != nil {
584					source = m[1]
585					break
586				}
587			}
588			if source == "" {
589				continue
590			}
591			var meta struct {
592				Kind     string `yaml:"kind"`
593				Metadata struct {
594					Name string `yaml:"name"`
595				} `yaml:"metadata"`
596			}
597			if yaml.Unmarshal([]byte(doc), &meta) != nil || meta.Kind == "" {
598				continue
599			}
600			key := meta.Kind + "/" + meta.Metadata.Name
601			if _, seen := origins[key]; seen {
602				continue
603			}
604			_, rest, _ := strings.Cut(source, "/")
605			origins[key] = path.Join(chart, rest)
606		}
607		return origins
608	}
609	
610	// splitYAMLDocuments splits a multi-document stream on its `---` separators.
611	func splitYAMLDocuments(stream []byte) []string {
612		var docs []string
613		var cur strings.Builder
614		r := bufio.NewReader(bytes.NewReader(stream))
615		for {
616			line, err := r.ReadString('\n')
617			if strings.TrimRight(line, "\r\n") == "---" {
618				docs = append(docs, cur.String())
619				cur.Reset()
620			} else {
621				cur.WriteString(line)
622			}
623			if errors.Is(err, io.EOF) || err != nil {
624				break
625			}
626		}
627		return append(docs, cur.String())
628	}
