18	// kubeconform validates Kubernetes manifests against the API's JSON schemas
19	// (§3.80): a wrong type, a missing required field, an unknown field under
20	// -strict, an apiVersion the target release no longer serves. Trivy's
21	// misconfiguration scan already lints the same files for security; this is
22	// the other question — whether the API server would accept them at all.
23	//
24	// Measured against kubeconform v0.8.0's sources, not its README: the JSON
25	// output, the status strings and the "could not find schema" wording below are
26	// what pkg/output/json.go and pkg/validator/validator.go write.
27	
28	// DefaultKubeconformImage is the image kubeconform runs from in a container.
29	// Its entrypoint is the binary itself, so the arguments follow the image name.
30	const DefaultKubeconformImage = "ghcr.io/yannh/kubeconform"
31	
32	// kubeconformCacheMount is where the schema cache is mounted in a container.
33	const kubeconformCacheMount = "/cache"
34	
35	// KubeconformOptions is what one validation run needs beyond the tool itself.
36	type KubeconformOptions struct {
37		// KubernetesVersion is the release to validate against, x.y.z or master.
38		KubernetesVersion string
39		// CacheDir is where downloaded schemas are kept between runs. Empty means
40		// every run downloads them again — slower, not wrong.
41		CacheDir string
42		// Helm and Kustomize render charts and overlays before validation. Either
43		// may be unresolved (Source none), which leaves what it would have
44		// rendered unvalidated and says so in the report.
45		Helm      ToolSpec
46		Kustomize ToolSpec
47	}
48	
49	// KubeconformReport is what one run found, beyond its findings.
50	type KubeconformReport struct {
51		Findings []Finding
52		// Validated is how many files were handed to kubeconform.
53		Validated int
54		// Unrendered are the charts and Kustomize overlays nobody validated,
55		// because the tool that renders them was not available. They are not
56		// errors — the scan did everything it could — but they are not "clean"
57		// either, and saying nothing would read as though they were.
58		Unrendered []string
59		// SkippedCustom counts resources whose kind no schema describes because it
60		// is a custom resource. Their schema lives in the CRD, which kubeconform
61		// does not read.
62		SkippedCustom int
63	}
64	
65	// kubeconformArgs builds the invocation over files relative to target.
66	//
67	// The files are passed explicitly rather than the directory: kubeconform
68	// reports "missing 'kind' key" on every YAML file that is not a manifest —
69	// a CI configuration, a Helm values file — and k8s.Discover has already told
70	// the two apart. The tool runs in target so the file names it reports are the
71	// relative ones the findings carry.
72	func kubeconformArgs(target string, files []string, tool ToolSpec, opts KubeconformOptions) toolCmd {
73		docker := tool.Source == ToolSourceContainer
74		flags := kubeconformFlags(tool, opts)
75	
76		if !docker {
77			args := append(flags, nativePaths(files)...)
78			return toolCmd{Name: kubeconformBinary(tool), Args: args, Dir: target}
79		}
80	
81		engineArgs := []string{"-v", target + ":" + containerScanPath + ":ro"}
82		if opts.CacheDir != "" {
83			engineArgs = append(engineArgs, "-v", opts.CacheDir+":"+kubeconformCacheMount)
84		}
85		engineArgs = append(engineArgs, "-w", containerScanPath)
86		// Inside the container the paths are Linux ones, whatever the host is.
87		return containerRun{Flags: engineArgs, Image: kubeconformImage(tool.Image), Argv: append(flags, files...)}.cmd()
88	}
89	
90	// kubeconformFlags are the options every validation run shares, raw files or
91	// rendered input.
92	func kubeconformFlags(tool ToolSpec, opts KubeconformOptions) []string {
93		// The user's flags first: there is no subcommand, and Go's flag package
94		// stops at the first positional argument.
95		flags := append(append([]string{}, tool.Args...), "-output", "json", "-strict")
96		if opts.KubernetesVersion != "" {
97			flags = append(flags, "-kubernetes-version", opts.KubernetesVersion)
98		}
99		if opts.CacheDir != "" {
100			cache := opts.CacheDir
101			if tool.Source == ToolSourceContainer {
102				cache = kubeconformCacheMount
103			}
104			flags = append(flags, "-cache", cache)
105		}
106		return flags
107	}
108	
109	// RunKubeconform finds the repository's manifests and validates them: the
110	// plain ones as files, the charts and overlays once rendered.
111	//
112	// The plain manifests are skipped when there are none rather than handed over
113	// as an empty list: kubeconform with no file argument reads stdin, and would
114	// wait there.
115	func RunKubeconform(ctx context.Context, target string, tool ToolSpec, opts KubeconformOptions, progressFn func(string)) (*KubeconformReport, error) {
116		layout, err := k8s.Discover(target)
117		if err != nil {
118			return nil, fmt.Errorf("listing manifests: %w", err)
119		}
120		if opts.CacheDir != "" {
121			if err := os.MkdirAll(opts.CacheDir, 0o755); err != nil {
122				// Validation still works without a cache; it downloads each time.
123				opts.CacheDir = ""
124			}
125		}
126		v := &k8sValidation{target: target, scope: targetOnly(target), kubeconform: tool, opts: opts,
127			report: &KubeconformReport{Validated: len(layout.Manifests)}}
128		// Only a renderer in a container needs more than the target mounted, and
129		// git is asked only when one is about to run.
130		if (len(layout.Charts) > 0 && opts.Helm.Source == ToolSourceContainer) ||
131			(len(layout.Kustomizations) > 0 && opts.Kustomize.Source == ToolSourceContainer) {
132			v.scope = resolveRenderScope(ctx, target)
133		}
134	
135		if len(layout.Manifests) > 0 {
136			if err := v.validateFiles(ctx, layout.Manifests, progressFn); err != nil {
137				return nil, err
138			}
139		}
140		if err := v.renderCharts(ctx, layout.Charts); err != nil {
141			return nil, err
142		}
143		if err := v.renderKustomizations(ctx, layout.Kustomizations); err != nil {
144			return nil, err
145		}
146		return v.report, nil
147	}
148	
149	// validateFiles validates plain manifests, where each finding can be given the
150	// line its pointer designates.
151	func (v *k8sValidation) validateFiles(ctx context.Context, files []string, progressFn func(string)) error {
152		cmd := kubeconformArgs(v.target, files, v.kubeconform, v.opts)
153		log.Printf("Running: %s", cmd)
154		out, err := runner.Run(ctx, cmd, progressFn)
155		if err := kubeconformFailure(out, err); err != nil {
156			return err
157		}
158		findings, skipped, err := parseKubeconformOutput(out, v.opts.KubernetesVersion, fileReader(v.target), nil)
159		if err != nil {
160			return err
161		}
162		v.stampSchemaRepro(findings)
163		v.report.Findings = append(v.report.Findings, findings...)
164		v.report.SkippedCustom += skipped
165		return nil
166	}
167	
168	// stampSchemaRepro records on each schema finding of a plain file where
169	// kubeconform ran and, when it ran on this machine, the command that checks that
170	// file again. DevDesk's own flags (-output json, -cache) are left out, and so are
171	// the user's arguments (scan.tools.kubeconform.args), which may hold a secret.
172	// K8S-API-REMOVED and K8S-PARSE carry neither (DEVDESK-752).
173	func (v *k8sValidation) stampSchemaRepro(findings []Finding) {
174		type reproLineFrom struct {
175			line string
176			from ToolSource
177		}
178		byFile := map[string]reproLineFrom{}
179		for i := range findings {
180			f := &findings[i]
181			if f.ID != K8sSchemaID {
182				continue
183			}
184			r, ok := byFile[f.File]
185			if !ok {
186				args := []string{"-strict"}
187				if v.opts.KubernetesVersion != "" {
188					args = append(args, "-kubernetes-version", v.opts.KubernetesVersion)
189				}
190				r.line, r.from = localRepro(v.kubeconform, "kubeconform", args, f.File)
191				byFile[f.File] = r
192			}
193			f.Repro, f.RanFrom = r.line, r.from
194		}
195	}
196	
197	// kubeconformFailure tells a run that found problems from one that failed.
198	// kubeconform exits 1 for both; what separates them is whether it wrote its
199	// JSON report.
200	func kubeconformFailure(out []byte, err error) error {
201		if err == nil {
202			return nil
203		}
204		var exitErr *exitError
205		if errors.As(err, &exitErr) && exitErr.Code == 1 && looksLikeJSON(out) {
206			return nil
207		}
208		return err
209	}
210	
211	func looksLikeJSON(out []byte) bool {
212		for _, b := range out {
213			switch b {
214			case ' ', '\n', '\r', '\t':
215				continue
216			case '{':
217				return true
218			default:
219				return false
220			}
221		}
222		return false
223	}
224	
225	// fileReader reads a file relative to root, for locating a finding's line.
226	func fileReader(root string) func(string) ([]byte, error) {
227		return func(name string) ([]byte, error) {
228			return os.ReadFile(filepath.Join(root, filepath.FromSlash(name))) //nolint:gosec // a manifest of the repository being scanned
229		}
230	}
231	
232	// nativePaths turns the discovered, slash-separated names into the host's.
233	func nativePaths(files []string) []string {
234		out := make([]string, len(files))
235		for i, f := range files {
236			out[i] = filepath.FromSlash(f)
237		}
238		return out
239	}
240	
241	func kubeconformImage(image string) string {
242		if image == "" {
243			return DefaultKubeconformImage
244		}
245		return image
246	}
247	
248	func kubeconformBinary(tool ToolSpec) string {
249		if tool.Binary != "" {
250			return tool.Binary
251		}
252		return "kubeconform"
253	}
254	
255	// KubeconformCacheDir is where schemas are cached: beside the scan caches,
256	// under ~/.devdesk/cache. Empty when there is no home directory, which only
257	// costs the cache.
258	func KubeconformCacheDir() string {
259		home, err := os.UserHomeDir()
260		if err != nil {
261			return ""
262		}
263		return filepath.Join(home, ".devdesk", "cache", "kubeconform")
264	}
265	
266	// kubernetesVersionPattern is what kubeconform accepts for -kubernetes-version:
267	// its own regexp, from pkg/config/config.go.
268	var kubernetesVersionPattern = regexp.MustCompile(`^(master|\d+\.\d+\.\d+)$`)
269	
270	// ValidateKubernetesVersion refuses what kubeconform would refuse, so the
271	// configuration view says it at the field rather than every scan failing on
272	// it. Empty is accepted: it means the default release.
273	func ValidateKubernetesVersion(v string) error {
274		if v == "" || kubernetesVersionPattern.MatchString(v) {
275			return nil
276		}
277		return fmt.Errorf("%q is not a version: use a full x.y.z such as %s, or master", v, config.DefaultKubernetesVersion)
278	}
279	
280	// kubeconformOptions is what this scanner validates against, and the
281	// renderers it has — an unavailable one is handed over unresolved.
282	func (s *Scanner) kubeconformOptions() KubeconformOptions {
283		opts := KubeconformOptions{KubernetesVersion: s.options.Tools.Kubeconform.KubernetesVersion, CacheDir: KubeconformCacheDir()}
284		// A renderer serves only when it is ticked: installed and unticked, it is
285		// not used (§3.86), and its charts or overlays are reported as not rendered.
286		if s.runs(CategoryIDMisconfig, ToolHelm, TargetDirectory) {
287			opts.Helm = s.spec(ToolHelm)
288		}
289		if s.runs(CategoryIDMisconfig, ToolKustomize, TargetDirectory) {
290			opts.Kustomize = s.spec(ToolKustomize)
291		}
292		return opts
293	}
294	
295	// runKubeconformStage is the schema stage of Scan, shaped like the others:
296	// progress, then findings or a stage error under the result's lock.
297	func (s *Scanner) runKubeconformStage(ctx context.Context, target string, result *Result, mu *sync.Mutex, notify func(ProgressUpdate)) {
298		const stage, label = "k8s-schema", "Kubernetes schema"
299		notify(ProgressUpdate{Stage: stage, Label: label, Status: StageRunning})
300		progressFn := func(detail string) {
301			notify(ProgressUpdate{Stage: stage, Label: label, Status: StageRunning, Detail: detail})
302		}
303		report, err := RunKubeconform(ctx, target, s.spec(ToolKubeconform), s.kubeconformOptions(), progressFn)
304	
305		mu.Lock()
306		defer mu.Unlock()
307		if err != nil {
308			recordStageError(result, "kubeconform", err)
309			notify(ProgressUpdate{Stage: stage, Label: label, Status: StageError, Detail: err.Error()})
310			return
311		}
312		if report.SkippedCustom > 0 {
313			log.Printf("[scan/kubeconform] %s: %d custom resources not validated (their schema is in a CRD)", target, report.SkippedCustom)
314		}
315		if len(report.Unrendered) > 0 {
316			log.Printf("[scan/kubeconform] %s: not rendered, so not validated: %s", target, strings.Join(report.Unrendered, ", "))
317		}
318		result.K8sUnrendered = report.Unrendered
319		result.Findings = append(result.Findings, report.Findings...)
320		// Schema validation is the second half of the Misconfiguration category, so
321		// a run of it makes the verdict known on its own: a repository scanned with
322		// Trivy's rules switched off but kubeconform on has been looked at, and a
323		// "-" there would say otherwise. What the stage could not render is carried
324		// in K8sUnrendered and comes back out as the column's "?".
325		result.MisconfigScanned = true
326		notify(ProgressUpdate{Stage: stage, Label: label, Status: StageDone})
327	}
