package scan

import (
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
)

// DEVDESK-752 (step 2): what a scan writes on the findings the schema stage and
// its renderers build — Steps always, Repro and RanFrom only when the tool ran on
// this machine and one plain command reproduces the finding.

// asContainers is the report with these tools run from an image.
func asContainers(r Report, ids ...ToolID) Report {
	tools := make(map[ToolID]ToolStatus, len(r.Tools))
	for k, v := range r.Tools {
		tools[k] = v
	}
	for _, id := range ids {
		tool, _ := ToolByID(id)
		tools[id] = ToolStatus{Available: true, Source: ToolSourceContainer, Image: tool.DefaultImage}
	}
	r.Tools = tools
	return r
}

// subcommandOf is the helm or kustomize subcommand an invocation carries, from a
// binary or from `run --rm … <image> <subcommand> …` alike.
func subcommandOf(tc toolCmd) string {
	for _, a := range tc.Args {
		switch a {
		case "lint", "template", "build":
			return a
		}
	}
	return ""
}

// failingRenderRunner answers kustomize build with an error and helm with its
// recorded lint output and a failing template. git (asked for the mount of a
// container renderer) has no repository to name.
func failingRenderRunner(t *testing.T, kustomizeStderr, helmStderr string) {
	t.Helper()
	lint, err := os.ReadFile(filepath.Join("testdata", "helm_lint_broken.txt"))
	if err != nil {
		t.Fatal(err)
	}
	useRunner(t, &scriptedRunner{reply: func(tc toolCmd) ([]byte, error) {
		if tc.Name == "git" {
			return nil, &exitError{Code: 128, Stderr: "not a git repository"}
		}
		switch subcommandOf(tc) {
		case "lint":
			return []byte(strings.ReplaceAll(string(lint), "charts/broken", "charts/api")), nil
		case "template":
			return nil, &exitError{Code: 1, Stderr: helmStderr}
		case "build":
			return nil, &exitError{Code: 1, Stderr: kustomizeStderr}
		}
		t.Errorf("unexpected invocation: %s", tc)
		return nil, nil
	}})
}

// findingWhere is the one finding of a result matching pred.
func findingWhere(t *testing.T, result *Result, what string, pred func(Finding) bool) Finding {
	t.Helper()
	var found []Finding
	for _, f := range result.Findings {
		if pred(f) {
			found = append(found, f)
		}
	}
	if len(found) != 1 {
		t.Fatalf("%d findings for %s, want 1, among %+v", len(found), what, result.Findings)
	}
	return found[0]
}

package scan

import (
	"os/exec"
	"strings"
	"unicode"
)

// shellMeta are the characters that make a shell read more than words in a
// command: separators, expansions, redirections, quoting, globbing, comments.
// The brackets are here for the glob they open (pkg[extra]).
const shellMeta = ";|&$`<>()\\'\"{}*?!#[]"

// wordHeadMeta are the characters a shell reads only at the head of a word: the
// home directory (~), the history substitution or glob negation (^), a job (%)
// and a command path (=, in zsh). Inside a word they are spellings real names
// and versions carry (semver@^6.3.1, 1:12.2.0~rc1-2, pkg==1.2,
// --flag=value), so only the head refuses them.
const wordHeadMeta = "~^%="

// PlainWords reports whether cmd is made of visible characters and single
// spaces, with no shell metacharacter. It is the one computation behind every
// command DevDesk offers to copy (DEVDESK-751, DEVDESK-752): the Run line of the
// finding detail, and a Repro line built here or read back from a cache.
func PlainWords(cmd string) bool {
	head := true
	for _, r := range cmd {
		switch {
		case r == ' ':
			head = true
			continue
		case unicode.IsControl(r), !unicode.IsPrint(r), strings.ContainsRune(shellMeta, r):
			return false
		case head && strings.ContainsRune(wordHeadMeta, r):
			return false
		}
		head = false
	}
	return true
}

// lookPath is the seam of the program name: whether the tool a scan ran is the
// one `name` resolves to on PATH. TestMain replaces it, so no test depends on
// the helm or the kustomize of the machine it runs on.
var lookPath = exec.LookPath

// reproLine joins a program, its arguments and the paths it works on into one
// line, or refuses.
//
// It refuses the whole line when a token is empty, holds a blank, or is not
// PlainWords: a path with a space gives no Repro rather than a command that
// splits it. A path that starts with "-" is refused too: once pasted, it would
// be read as an option. Nothing is quoted.
func reproLine(program string, args []string, paths ...string) (string, bool) {
	tokens := append(append([]string{program}, args...), paths...)
	for _, tok := range tokens {
		if tok == "" || strings.ContainsFunc(tok, unicode.IsSpace) || !PlainWords(tok) {
			return "", false
		}
	}
	for _, p := range paths {
		if strings.HasPrefix(p, "-") {
			return "", false
		}
	}
	return strings.Join(tokens, " "), true
}

// reproProgram is the name to show for a program: the plain tool name when
// look finds the same binary (or when no binary is configured), else the
// configured path, which is what ran.
func reproProgram(binary, name string, look func(string) (string, error)) string {
	if binary == "" {
		return name
	}
	if found, err := look(name); err == nil && found == binary {
		return name
	}
	return binary
}

// localRepro is the Repro line of a finding one tool command could reproduce,
// and where the tool ran. A tool in a container gives no line and says so by its
// source; a line that cannot be written plainly gives none either. name is the
}

func renderFindingOf(t *testing.T, result *Result) Finding {
	return findingWhere(t, result, "the render failure", func(f Finding) bool { return f.ID == K8sRenderID })
}

