		Charts:         []string{"-x"},
		Kustomizations: []string{"--load-restrictor=LoadRestrictionsNone"},
	}
	if !reflect.DeepEqual(layout, want) {
		t.Errorf("layout = %+v, want %+v", layout, want)
	}
}
